// gbench.cu -- isolated DRAM-bandwidth ceiling for the page_size=1 paged-KV decode access pattern.
// Reproduces the exact memory shape of attn_real_llama8b_dec_s16k (batch16 x hkv8 -> 128 CTAs,
// 128 tiles of 128 keys, 64 KB/tile K+V, 3-deep mbarrier ring, 1 CTA/SM) with ZERO attention math.
//
// nvcc -O3 -arch=sm_100a -lcuda /tmp/gbench.cu -o /tmp/gbench
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <vector>
#include <string>
#include <random>
#include <algorithm>
#include <functional>

#define CK(x) do{ cudaError_t e_=(x); if(e_!=cudaSuccess){ printf("CUDA ERR %s @%d: %s\n",#x,__LINE__,cudaGetErrorString(e_)); exit(1);} }while(0)
#define CKD(x) do{ CUresult e_=(x); if(e_!=CUDA_SUCCESS){ const char*s_; cuGetErrorString(e_,&s_); printf("CU ERR %s @%d: %s\n",#x,__LINE__,s_); exit(1);} }while(0)

// ---------------- workload geometry (matches attn_real_llama8b_dec_s16k) ----------------
static const int HKV = 8, HD = 128, HDV = 128;
static const int RW = HKV * HD;                 // 1024 bf16 elems per pool row == 2048 B
static const int BATCH = 16, SEQ = 16384;
static const int NROWS = BATCH * SEQ;           // 262144 rows
static const size_t POOL_ELEMS = (size_t)NROWS * RW;
static const size_t POOL_BYTES = POOL_ELEMS * 2;             // 536,870,912 B per tensor
static const int NTHREADS = 512;
static const int NCTA = 128;                    // batch16 * hkv8
static const int SMEM_REQ = 224 * 1024;         // force exactly 1 CTA/SM

enum { V_G4_DIV = 0, V_G4_WU = 1, V_CPASYNC = 2, V_BULK = 3, V_TMAFULL = 4, V_LDG = 5 };

// ---------------- PTX helpers (verbatim shapes from kernels/fa4_blackwell.cu) ----------------
__device__ __forceinline__ uint32_t sm32(const void* p){ return (uint32_t)__cvta_generic_to_shared(p); }
__device__ __forceinline__ void mbar_init(uint32_t m,int c){ asm volatile("mbarrier.init.shared.b64 [%0], %1;"::"r"(m),"r"(c)); }
__device__ __forceinline__ void mbar_arrive(uint32_t m){ asm volatile("mbarrier.arrive.shared.b64 _, [%0];"::"r"(m)); }
__device__ __forceinline__ void mbar_expect(uint32_t m,int b){ asm volatile("mbarrier.arrive.expect_tx.shared.b64 _, [%0], %1;"::"r"(m),"r"(b)); }
__device__ __forceinline__ void mbar_wait(uint32_t m,int ph){
    asm volatile("{ .reg .pred P;\nLW: mbarrier.try_wait.parity.shared.b64 P,[%0],%1,10000000;\n @P bra D; bra LW;\nD: }"::"r"(m),"r"(ph)); }
__device__ __forceinline__ void cp_async_mbar_arrive(uint32_t m){
    asm volatile("cp.async.mbarrier.arrive.noinc.shared::cta.b64 [%0];"::"r"(m):"memory"); }
__device__ __forceinline__ void tma_box(void* dst,const void* map,int x,int y,uint32_t bar){
    asm volatile("cp.async.bulk.tensor.2d.shared::cluster.global.tile.mbarrier::complete_tx::bytes [%0], [%1, {%2,%3}], [%4];"
                 :: "r"(sm32(dst)),"l"(map),"r"(x),"r"(y),"r"(bar) : "memory"); }
__device__ __forceinline__ void tma_gather4(void* dst,const void* map,int x,int y0,int y1,int y2,int y3,uint32_t bar){
    asm volatile("cp.async.bulk.tensor.2d.tile::gather4.shared::cta.global.mbarrier::complete_tx::bytes"
                 " [%0], [%1, {%2,%3,%4,%5,%6}], [%7];"
                 :: "r"(sm32(dst)),"l"(map),"r"(x),"r"(y0),"r"(y1),"r"(y2),"r"(y3),"r"(bar) : "memory"); }
__device__ __forceinline__ void bulk_copy(void* dst,const void* src,int bytes,uint32_t bar){
    asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes [%0], [%1], %2, [%3];"
                 :: "r"(sm32(dst)),"l"(src),"r"(bytes),"r"(bar) : "memory"); }

// ---------------- the benchmark kernel ----------------
// VAR   : loader variant
// WTN   : keys per tile
// DEPTH : smem ring depth
// NLW   : number of LOAD warps (rest of the 16 warps are consumers)
template<int VAR,int WTN,int DEPTH,int NLW>
__global__ void __launch_bounds__(NTHREADS,1)
kbench(const __grid_constant__ CUtensorMap mK, const __grid_constant__ CUtensorMap mV,
       const uint16_t* __restrict__ kp, const uint16_t* __restrict__ vp,
       const int* __restrict__ pt, unsigned* sink, int chk)
{
    constexpr int NTILES = SEQ / WTN;
    constexpr int LN  = NLW * 32;
    constexpr int NCW = 16 - NLW;
    constexpr int NCT = NCW * 32;
    constexpr int KTE = WTN * HD, VTE = WTN * HDV;      // elems per K / V tile
    constexpr int CB  = HD / 64;                        // 64-col blocks per tensor (2 at hd128)
    constexpr int NG  = WTN / 4;                        // gather4 key-groups
    constexpr int CBS = WTN * 64;                       // elems per (column-block) in swizzled tile
    constexpr int TILE_BYTES = (KTE + VTE) * 2;

    const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
    const int b = blockIdx.x >> 3, h = blockIdx.x & 7;
    const int* __restrict__ ptb = pt + (size_t)b * SEQ;

    extern __shared__ __align__(1024) char smraw[];
    uint16_t* sKb = (uint16_t*)smraw;
    uint16_t* sVb = sKb + DEPTH * KTE;
    uint64_t* barb = (uint64_t*)(sVb + DEPTH * VTE);
    int* prowb = (int*)(barb + 2 * DEPTH);

    // ---------------- G: plain LDG.128 straight to registers, no smem staging ----------------
    if (VAR == V_LDG) {
        unsigned acc = 0;
        for (int i = 0; i < NTILES; ++i) {
            const int key0 = i * WTN;
            #pragma unroll 4
            for (int idx = tid; idx < 2 * WTN * (HD / 8); idx += NTHREADS) {
                int t = idx;  bool isK = t < WTN * (HD / 8);  if (!isK) t -= WTN * (HD / 8);
                int r = t / (HD / 8), c = (t % (HD / 8)) * 8;
                int prw = ptb[key0 + r];
                const uint16_t* src = (isK ? kp : vp) + (size_t)prw * RW + (size_t)h * HD + c;
                uint4 a = *(const uint4*)src;
                acc += a.x + a.y + a.z + a.w;
            }
        }
        atomicAdd(sink, acc);
        return;
    }

    constexpr int FULLCNT = (VAR == V_G4_DIV) ? 1
                          : (VAR == V_G4_WU)  ? NLW
                          : (VAR == V_CPASYNC)? LN
                          : (VAR == V_BULK)   ? NLW
                          : /* V_TMAFULL */     4;
    const uint32_t B0 = sm32(barb);
    if (tid < DEPTH)                    mbar_init(B0 + tid * 8, FULLCNT);
    else if (tid < 2 * DEPTH)           mbar_init(B0 + tid * 8, NCW);
    asm volatile("fence.proxy.async.shared::cta;");
    __syncthreads();

    if (warp < NLW) {
        // ================= PRODUCER =================
        const int lid = tid, lw = warp;
        int s = 0, kk = 0;
        for (int i = 0; i < NTILES; ++i) {
            const uint32_t full = B0 + s * 8, empty = B0 + (DEPTH + s) * 8;
            mbar_wait(empty, (kk + 1) & 1);                 // kk==0 -> free pass (DEPTH tiles of runway)
            const int key0 = i * WTN;
            uint16_t* sKs = sKb + s * KTE;
            uint16_t* sVs = sVb + s * VTE;
            int* prow = prowb + s * WTN;

            if (VAR == V_G4_DIV) {
                for (int r = lid; r < WTN; r += LN) prow[r] = ptb[key0 + r];
                if (lid == 0) mbar_expect(full, TILE_BYTES);
                asm volatile("bar.sync 8, %0;"::"r"(LN));
                constexpr int NGK = NG * CB, NGT = NGK + NG * CB;
                for (int op = lid; op < NGT; op += LN) {                 // DIVERGENT lanes: op = tid
                    bool isK = op < NGK; int o = isK ? op : op - NGK;
                    int cb = o / NG, g = o - cb * NG;
                    int y0 = prow[4*g], y1 = prow[4*g+1], y2 = prow[4*g+2], y3 = prow[4*g+3];
                    if (isK) tma_gather4(sKs + cb*CBS + 4*g*64, &mK, h*HD + cb*64, y0,y1,y2,y3, full);
                    else     tma_gather4(sVs + cb*CBS + 4*g*64, &mV, h*HD + cb*64, y0,y1,y2,y3, full);
                }
            }
            else if (VAR == V_G4_WU) {
                const int g0 = (NG * lw) / NLW, g1 = (NG * (lw + 1)) / NLW, ng = g1 - g0;
                if (ng <= 0) { if (lane == 0) mbar_arrive(full); }
                else {
                    for (int j = lane; j < 4 * ng; j += 32) { int r = 4*g0 + j; prow[r] = ptb[key0 + r]; }
                    __syncwarp();
                    if (lane == 0) {
                        mbar_expect(full, ng * (CB + CB) * 512);
                        for (int g = g0; g < g1; ++g) {
                            int y0 = prow[4*g], y1 = prow[4*g+1], y2 = prow[4*g+2], y3 = prow[4*g+3];
                            #pragma unroll
                            for (int cb = 0; cb < CB; ++cb) tma_gather4(sKs + cb*CBS + 4*g*64, &mK, h*HD + cb*64, y0,y1,y2,y3, full);
                            #pragma unroll
                            for (int cb = 0; cb < CB; ++cb) tma_gather4(sVs + cb*CBS + 4*g*64, &mV, h*HD + cb*64, y0,y1,y2,y3, full);
                        }
                    }
                }
            }
            else if (VAR == V_CPASYNC) {
                for (int r = lid; r < WTN; r += LN) prow[r] = ptb[key0 + r];
                asm volatile("bar.sync 8, %0;"::"r"(LN));
                #pragma unroll 4
                for (int idx = lid; idx < WTN * (HD / 8); idx += LN) {
                    int r = idx / (HD/8), c = (idx - r*(HD/8)) * 8; int prw = prow[r];
                    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"
                        ::"r"(sm32(&sKs[(c>>6)*CBS + r*64 + ((c&63)^((r&7)<<3))])),
                          "l"(&kp[(size_t)prw*RW + (size_t)h*HD + c]));
                }
                #pragma unroll 4
                for (int idx = lid; idx < WTN * (HDV / 8); idx += LN) {
                    int r = idx / (HDV/8), c = (idx - r*(HDV/8)) * 8; int prw = prow[r];
                    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"
                        ::"r"(sm32(&sVs[(c>>6)*CBS + r*64 + ((c&63)^((r&7)<<3))])),
                          "l"(&vp[(size_t)prw*RW + (size_t)h*HDV + c]));
                }
                cp_async_mbar_arrive(full);                  // deferred: no wait_group, producer runs ahead
            }
            else if (VAR == V_BULK) {
                // one non-tensor bulk copy per 256 B (row,head) slab -> LINEAR smem dst (a 256 B
                // contiguous copy cannot express the 128 B XOR swizzle; irrelevant for DRAM bandwidth).
                for (int r = lid; r < WTN; r += LN) prow[r] = ptb[key0 + r];
                asm volatile("bar.sync 8, %0;"::"r"(LN));
                const int o0 = (2*WTN*lw)/NLW, o1 = (2*WTN*(lw+1))/NLW;
                if (lane == 0) {
                    mbar_expect(full, (o1 - o0) * 256);
                    for (int o = o0; o < o1; ++o) {
                        bool isK = o < WTN; int r = isK ? o : o - WTN; int prw = prow[r];
                        if (isK) bulk_copy(sKs + r*HD,  kp + (size_t)prw*RW + (size_t)h*HD,  256, full);
                        else     bulk_copy(sVs + r*HDV, vp + (size_t)prw*RW + (size_t)h*HDV, 256, full);
                    }
                }
            }
            else if (VAR == V_TMAFULL) {
                // full-width contiguous TMA: box [64, WTN] over the pool.  Only correct for arange.
                if (lw < 4 && lane == 0) {
                    int cb = lw & 1; bool isK = lw < 2;
                    mbar_expect(full, 64 * WTN * 2);
                    int y = b * SEQ + key0;
                    if (isK) tma_box(sKs + cb*CBS, &mK, h*HD + cb*64, y, full);
                    else     tma_box(sVs + cb*CBS, &mV, h*HD + cb*64, y, full);
                }
            }
            if (++s == DEPTH) { s = 0; ++kk; }
        }
    } else {
        // ================= CONSUMER =================
        const int ct = (warp - NLW) * 32 + lane;
        unsigned acc = 0;
        int s = 0, kk = 0;
        for (int i = 0; i < NTILES; ++i) {
            const uint32_t full = B0 + s * 8, empty = B0 + (DEPTH + s) * 8;
            mbar_wait(full, kk & 1);
            if (chk) {                                       // full-tile checksum (verifies bytes moved)
                const uint4* pk = (const uint4*)(sKb + s*KTE);
                const uint4* pv = (const uint4*)(sVb + s*VTE);
                for (int j = ct; j < KTE/8; j += NCT) { uint4 a = pk[j]; acc += a.x+a.y+a.z+a.w; }
                for (int j = ct; j < VTE/8; j += NCT) { uint4 a = pv[j]; acc += a.x+a.y+a.z+a.w; }
            } else {                                         // trivial sink: 1 elem per slot per thread
                acc += ((const unsigned*)(sKb + s*KTE))[ct*4];
                acc += ((const unsigned*)(sVb + s*VTE))[ct*4];
            }
            __syncwarp();
            if (lane == 0) mbar_arrive(empty);
            if (++s == DEPTH) { s = 0; ++kk; }
        }
        atomicAdd(sink, acc);
    }
}

// ---------------- support kernels ----------------
__global__ void fill_pool(uint16_t* p, size_t n, unsigned seed){
    size_t st = (size_t)blockDim.x*gridDim.x;
    for (size_t i = (size_t)blockIdx.x*blockDim.x+threadIdx.x; i < n; i += st) {
        unsigned x = (unsigned)i * 2654435761u + seed; x ^= x >> 15; x *= 2246822519u; x ^= x >> 13;
        p[i] = (uint16_t)(x & 0xffff);
    }
}
__global__ void sum_words(const unsigned* p, size_t n, unsigned* out){
    unsigned a = 0; size_t st = (size_t)blockDim.x*gridDim.x;
    for (size_t i = (size_t)blockIdx.x*blockDim.x+threadIdx.x; i < n; i += st) a += p[i];
    atomicAdd(out, a);
}
__global__ void flushk(uint4* p, size_t n){
    size_t st = (size_t)blockDim.x*gridDim.x;
    for (size_t i = (size_t)blockIdx.x*blockDim.x+threadIdx.x; i < n; i += st) p[i] = make_uint4(i,i,i,i);
}
__global__ void roofk(const uint4* __restrict__ p, size_t n, unsigned* sink){
    unsigned a = 0; size_t st = (size_t)blockDim.x*gridDim.x;
    size_t i = (size_t)blockIdx.x*blockDim.x+threadIdx.x;
    for (; i + 3*st < n; i += 4*st) {
        uint4 x0=p[i], x1=p[i+st], x2=p[i+2*st], x3=p[i+3*st];
        a += x0.x+x0.y+x0.z+x0.w; a += x1.x+x1.y+x1.z+x1.w;
        a += x2.x+x2.y+x2.z+x2.w; a += x3.x+x3.y+x3.z+x3.w;
    }
    for (; i < n; i += st) { uint4 x=p[i]; a += x.x+x.y+x.z+x.w; }
    atomicAdd(sink, a);
}
// dependent-load pointer chase over a 512 MB region (one random cycle over 4096 B slots)
__global__ void chasek(const int* ring, int steps, unsigned* out){
    int p = 0;
    for (int i = 0; i < steps; ++i) p = ring[(size_t)p * 1024];
    out[0] = (unsigned)p;
}

// ---------------- host ----------------
static uint16_t *dK, *dV; static int *dPTa, *dPTp; static unsigned* dSink;
static uint4* dFlush; static uint4* dRoof; static int* dRing;
static size_t FLUSH_U4, ROOF_U4;
static unsigned REF_SUM;
static cudaEvent_t ev0, ev1;

static CUtensorMap make_map(void* ptr, int boxrows){
    CUtensorMap m{};
    uint64_t gdim[2] = {(uint64_t)RW, (uint64_t)NROWS};
    uint64_t gstride[1] = {(uint64_t)(RW * 2)};
    uint32_t bdim[2] = {64u, (uint32_t)boxrows};
    uint32_t estride[2] = {1u, 1u};
    CKD(cuTensorMapEncodeTiled(&m, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 2, ptr, gdim, gstride, bdim, estride,
        CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B,
        CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE));
    return m;
}
static void flush_l2(){ flushk<<<148*8, 256>>>(dFlush, FLUSH_U4); }

struct Res { double gbs_mean, gbs_best, us_mean, us_best; unsigned sum; bool ok; };

template<int VAR,int WTN,int DEPTH,int NLW>
Res run_cfg(bool perm, int iters, int chk, bool ncu_single){
    auto fn = kbench<VAR,WTN,DEPTH,NLW>;
    CK(cudaFuncSetAttribute(fn, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_REQ));
    int boxrows = (VAR == V_TMAFULL) ? WTN : 1;
    CUtensorMap mk = make_map(dK, boxrows), mv = make_map(dV, boxrows);
    int* pt = perm ? dPTp : dPTa;
    const double bytes = 2.0 * (double)POOL_BYTES;                 // 1.0737 GB of useful K+V

    // ---- correctness pass: full-tile checksum must equal the whole-pool word sum ----
    CK(cudaMemset(dSink, 0, 4));
    fn<<<NCTA, NTHREADS, SMEM_REQ>>>(mk, mv, dK, dV, pt, dSink, 1);
    CK(cudaDeviceSynchronize());
    unsigned got = 0; CK(cudaMemcpy(&got, dSink, 4, cudaMemcpyDeviceToHost));
    Res r{}; r.ok = (got == REF_SUM); r.sum = got;

    if (ncu_single) { CK(cudaMemset(dSink,0,4)); flush_l2();
        fn<<<NCTA,NTHREADS,SMEM_REQ>>>(mk,mv,dK,dV,pt,dSink,chk); CK(cudaDeviceSynchronize()); return r; }

    for (int i = 0; i < 3; ++i) { flush_l2(); fn<<<NCTA,NTHREADS,SMEM_REQ>>>(mk,mv,dK,dV,pt,dSink,chk); }
    CK(cudaDeviceSynchronize());
    double tot = 0, best = 1e30;
    for (int i = 0; i < iters; ++i) {
        flush_l2();
        CK(cudaEventRecord(ev0));
        fn<<<NCTA,NTHREADS,SMEM_REQ>>>(mk,mv,dK,dV,pt,dSink,chk);
        CK(cudaEventRecord(ev1));
        CK(cudaEventSynchronize(ev1));
        float ms = 0; CK(cudaEventElapsedTime(&ms, ev0, ev1));
        tot += ms; if (ms < best) best = ms;
    }
    CK(cudaGetLastError());
    double ms_mean = tot / iters;
    r.us_mean = ms_mean * 1e3; r.us_best = best * 1e3;
    r.gbs_mean = bytes / (ms_mean * 1e-3) / 1e9;
    r.gbs_best = bytes / (best   * 1e-3) / 1e9;
    return r;
}

struct Entry { std::string name; std::string note; std::function<Res(bool,int,int,bool)> f; bool arange_only; };
static std::vector<Entry> ents;
template<int VAR,int WTN,int DEPTH,int NLW>
static void reg(const char* name, const char* note, bool arange_only=false){
    ents.push_back({name, note, run_cfg<VAR,WTN,DEPTH,NLW>, arange_only});
}

int main(int argc, char** argv){
    std::string mode = argc > 1 ? argv[1] : "all";
    std::string pick = argc > 2 ? argv[2] : "";
    std::string ptsel = argc > 3 ? argv[3] : "both";
    int iters = argc > 4 ? atoi(argv[4]) : 20;
    int chk = argc > 5 ? atoi(argv[5]) : 0;

    CK(cudaSetDevice(0));
    cudaDeviceProp pr; CK(cudaGetDeviceProperties(&pr, 0));
    int optin = 0; CK(cudaDeviceGetAttribute(&optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, 0));

    CK(cudaMalloc(&dK, POOL_BYTES));
    CK(cudaMalloc(&dV, POOL_BYTES));
    FLUSH_U4 = (512ull << 20) / 16; CK(cudaMalloc(&dFlush, 512ull << 20));
    ROOF_U4  = (2048ull << 20) / 16; CK(cudaMalloc(&dRoof, 2048ull << 20));
    CK(cudaMalloc(&dPTa, (size_t)NROWS * 4));
    CK(cudaMalloc(&dPTp, (size_t)NROWS * 4));
    CK(cudaMalloc(&dSink, 8));
    CK(cudaEventCreate(&ev0)); CK(cudaEventCreate(&ev1));

    fill_pool<<<148*8,256>>>(dK, POOL_ELEMS, 12345u);
    fill_pool<<<148*8,256>>>(dV, POOL_ELEMS, 98765u);
    fill_pool<<<148*8,256>>>((uint16_t*)dRoof, ROOF_U4*8, 555u);
    CK(cudaMemset(dSink, 0, 4));
    sum_words<<<148*8,256>>>((const unsigned*)dK, POOL_BYTES/4, dSink);
    sum_words<<<148*8,256>>>((const unsigned*)dV, POOL_BYTES/4, dSink);
    CK(cudaDeviceSynchronize());
    CK(cudaMemcpy(&REF_SUM, dSink, 4, cudaMemcpyDeviceToHost));

    { std::vector<int> a(NROWS); for (int i=0;i<NROWS;++i) a[i]=i;
      CK(cudaMemcpy(dPTa, a.data(), (size_t)NROWS*4, cudaMemcpyHostToDevice));
      std::mt19937 g(7); std::shuffle(a.begin(), a.end(), g);
      CK(cudaMemcpy(dPTp, a.data(), (size_t)NROWS*4, cudaMemcpyHostToDevice)); }

    printf("# device: %s  SMs=%d  clk=%.2f GHz  L2=%.1f MB  optin smem=%d B  smem_req=%d B\n",
           pr.name, pr.multiProcessorCount, pr.clockRate/1e6, pr.l2CacheSize/1048576.0, optin, SMEM_REQ);
    printf("# pool: 2 x %.2f MB = %.4f GB useful;  %d CTAs x %d thr;  ref_sum=0x%08x\n",
           POOL_BYTES/1048576.0, 2.0*POOL_BYTES/1e9, NCTA, NTHREADS, REF_SUM);

    // ------------- registry -------------
    //          VAR         WTN DEPTH NLW
    reg<V_G4_DIV, 128,3,11>("A_gather4_divergent",   "128 issues/tile, op=tid (4 warps replay 32x)");
    reg<V_G4_WU,  128,3,11>("B_gather4_warpuni_11w", "128 issues/tile, 11 load warps, lane0");
    reg<V_G4_WU,  128,3,4 >("C_gather4_warpuni_4w",  "128 issues/tile, 4 load warps");
    reg<V_G4_WU,  128,3,8 >("C_gather4_warpuni_8w",  "128 issues/tile, 8 load warps");
    reg<V_G4_WU,  128,3,15>("C_gather4_warpuni_15w", "128 issues/tile, 15 load warps");
    reg<V_CPASYNC,128,3,3 >("D_cpasync_96thr",       "4096x16B/tile, 3 warps (fa4_paged real cfg)");
    reg<V_CPASYNC,128,3,4 >("D_cpasync_128thr",      "4096x16B/tile, 4 warps, 16 cp/thr/tensor");
    reg<V_CPASYNC,128,3,11>("D_cpasync_352thr",      "4096x16B/tile, 11 warps");
    reg<V_BULK,   128,3,11>("E_bulk256_11w",         "256 non-tensor bulk copies of 256B/tile");
    reg<V_BULK,   128,3,4 >("E_bulk256_4w",          "256 non-tensor bulk copies of 256B/tile");
    reg<V_TMAFULL,128,3,4 >("F_tma_full_box64x128",  "4 TMA boxes of 16KB/tile (contiguous only)", true);
    reg<V_LDG,    128,3,4 >("G_ldg128_reg",          "LDG.128 -> registers, no smem staging");
    // ring-depth sweep
    reg<V_G4_WU,  128,2,11>("S_g4wu_wtn128_d2",      "depth sweep");
    reg<V_G4_WU,  64, 2,11>("S_g4wu_wtn64_d2",       "depth sweep");
    reg<V_G4_WU,  64, 3,11>("S_g4wu_wtn64_d3",       "depth sweep");
    reg<V_G4_WU,  64, 4,11>("S_g4wu_wtn64_d4",       "depth sweep");
    reg<V_G4_WU,  64, 6,11>("S_g4wu_wtn64_d6",       "depth sweep");
    reg<V_CPASYNC,128,2,11>("S_cpa_wtn128_d2",       "depth sweep");
    reg<V_CPASYNC,64, 2,11>("S_cpa_wtn64_d2",        "depth sweep");
    reg<V_CPASYNC,64, 3,11>("S_cpa_wtn64_d3",        "depth sweep");
    reg<V_CPASYNC,64, 4,11>("S_cpa_wtn64_d4",        "depth sweep");
    reg<V_CPASYNC,64, 6,11>("S_cpa_wtn64_d6",        "depth sweep");
    reg<V_CPASYNC,128,3,7 >("S_cpa_wtn128_d3_7w",    "load-warp sweep");
    reg<V_CPASYNC,128,3,15>("S_cpa_wtn128_d3_15w",   "load-warp sweep");
    reg<V_TMAFULL,128,2,4 >("S_tmafull_d2",          "depth sweep", true);

    if (mode == "list") { for (auto& e : ents) printf("%s\n", e.name.c_str()); return 0; }

    // ------------- contiguous streaming roof -------------
    if (mode == "all" || mode == "roof") {
        for (int i=0;i<3;++i){ flush_l2(); roofk<<<148*8,512>>>(dRoof, ROOF_U4, dSink); }
        CK(cudaDeviceSynchronize());
        double tot=0,best=1e30;
        for (int i=0;i<iters;++i){ flush_l2(); CK(cudaEventRecord(ev0));
            roofk<<<148*8,512>>>(dRoof, ROOF_U4, dSink); CK(cudaEventRecord(ev1));
            CK(cudaEventSynchronize(ev1)); float ms=0; CK(cudaEventElapsedTime(&ms,ev0,ev1));
            tot+=ms; if(ms<best)best=ms; }
        double bytes = (double)ROOF_U4*16;
        printf("ROOF  2GB grid-stride uint4 read : %.1f GB/s mean (%.1f best), %.1f us\n",
               bytes/(tot/iters*1e-3)/1e9, bytes/(best*1e-3)/1e9, tot/iters*1e3);
    }
    // ------------- DRAM latency (dependent-load pointer chase, 512 MB region) -------------
    if (mode == "all" || mode == "lat") {
        const int NSLOT = (int)((512ull<<20)/4096);
        std::vector<int> nxt(NSLOT); { std::vector<int> ord(NSLOT);
            for(int i=0;i<NSLOT;++i) ord[i]=i; std::mt19937 g(11);
            std::shuffle(ord.begin()+1, ord.end(), g);
            for(int i=0;i<NSLOT;++i) nxt[ord[i]] = ord[(i+1)%NSLOT]; }
        // write nxt[] into the flush buffer at 4096 B stride
        std::vector<int> host((size_t)NSLOT*1024, 0);
        for (int i=0;i<NSLOT;++i) host[(size_t)i*1024] = nxt[i];
        CK(cudaMemcpy(dFlush, host.data(), (size_t)NSLOT*4096, cudaMemcpyHostToDevice));
        dRing = (int*)dFlush;
        int steps = 20000;
        chasek<<<1,1>>>(dRing, 1000, dSink); CK(cudaDeviceSynchronize());
        CK(cudaEventRecord(ev0)); chasek<<<1,1>>>(dRing, steps, dSink); CK(cudaEventRecord(ev1));
        CK(cudaEventSynchronize(ev1)); float ms=0; CK(cudaEventElapsedTime(&ms,ev0,ev1));
        printf("LAT   dependent-load chase over 512MB : %.1f ns/hop  (%d steps, %.3f ms)\n",
               ms*1e6/steps, steps, ms);
        // rebuild flush buffer content is irrelevant (it is write-only afterwards)
    }
    if (mode == "roof" || mode == "lat") return 0;

    printf("\n%-26s %-8s %10s %10s %10s %10s  %s\n","variant","pagetbl","GB/s(mean)","GB/s(best)","us(mean)","us(best)","chk");
    for (auto& e : ents) {
        if (!pick.empty() && e.name.find(pick) == std::string::npos) continue;
        for (int p = 0; p < 2; ++p) {
            const char* pn = p ? "perm" : "arange";
            if (ptsel != "both" && ptsel != pn) continue;
            if (p && e.arange_only) { printf("%-26s %-8s %10s\n", e.name.c_str(), pn, "N/A"); continue; }
            Res r = e.f(p != 0, iters, chk, mode == "ncu");
            if (mode == "ncu") { printf("%-26s %-8s  (ncu single launch) chk=%s\n", e.name.c_str(), pn, r.ok?"OK":"FAIL"); continue; }
            printf("%-26s %-8s %10.1f %10.1f %10.1f %10.1f  %s\n", e.name.c_str(), pn,
                   r.gbs_mean, r.gbs_best, r.us_mean, r.us_best, r.ok ? "OK" : "MISMATCH!");
        }
    }
    return 0;
}

